"""Synthetic documents for the PDF, image, OCR, EML and ZIP extractors.

Everything is generated by code: PDFs with reportlab (PyMuPDF only to add
the active content a hostile PDF would carry), images with Pillow (its
built-in font, so no system font is needed), mail with the standard
library's ``email`` package, archives with ``zipfile``. Names, merchants and
amounts are invented.
"""

from __future__ import annotations

import importlib
import io
import struct
import zipfile
import zlib
from collections.abc import Sequence
from email.message import EmailMessage
from email.policy import default as default_policy
from typing import Any

from PIL import Image, ImageDraw, ImageFont
from reportlab.lib.pagesizes import letter
from reportlab.lib.utils import ImageReader
from reportlab.pdfgen import canvas

STATEMENT_ROWS: tuple[tuple[str, str, str], ...] = (
    ("2026-01-03", "COFFEE CORNER", "-4.50"),
    ("2026-01-05", "EXAMPLE PAYROLL", "2500.00"),
    ("2026-01-09", "GREEN GROCER", "-82.17"),
    ("2026-01-12", "PARKSIDE RENT", "-1200.00"),
    ("2026-01-20", "CITY POWER", "-61.05"),
)


def _font(size: int) -> ImageFont.FreeTypeFont | ImageFont.ImageFont:
    return ImageFont.load_default(size=size)


def text_image(
    lines: Sequence[str],
    *,
    size: tuple[int, int] = (1700, 2200),
    font_size: int = 40,
    origin: tuple[int, int] = (150, 200),
    spacing: int = 80,
    angle: float = 0.0,
    mode: str = "L",
) -> Image.Image:
    """A white page with black text lines (a "scan"), optionally rotated by ``angle``."""
    image = Image.new(mode, size, 255 if mode == "L" else (255, 255, 255))
    draw = ImageDraw.Draw(image)
    font = _font(font_size)
    x, y = origin
    for line in lines:
        draw.text((x, y), line, fill=0 if mode == "L" else (0, 0, 0), font=font)
        y += spacing
    if angle:
        image = image.rotate(angle, expand=False, fillcolor=255 if mode == "L" else "white")
    return image


def image_bytes(image: Image.Image, fmt: str, **save: object) -> bytes:
    out = io.BytesIO()
    image.save(out, format=fmt, **save)
    return out.getvalue()


def statement_pdf(
    rows: Sequence[tuple[str, str, str]] = STATEMENT_ROWS,
    *,
    ruled: bool = False,
    pages: int = 1,
    title: str = "Example Savings Bank",
) -> bytes:
    """A text-layer statement: a heading, then date / payee / amount columns."""
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    c.setTitle(title)
    for page in range(pages):
        c.setFont("Helvetica", 11)
        c.drawString(72, 740, f"{title} - Statement period 2026-01-01 to 2026-01-31")
        c.drawString(72, 724, f"Account ending 4321 - page {page + 1}")
        cols = (72, 170, 380, 500)
        top = 690
        header = ("Date", "Description", "Amount")
        table = [header, *rows]
        for i, (d, p, a) in enumerate(table):
            y = top - i * 20
            c.drawString(cols[0] + 4, y - 14, d)
            c.drawString(cols[1] + 4, y - 14, p)
            c.drawRightString(cols[3] - 4, y - 14, a)
        if ruled:
            for i in range(len(table) + 1):
                c.line(cols[0], top - i * 20, cols[3], top - i * 20)
            for x in cols:
                c.line(x, top, x, top - len(table) * 20)
        c.drawString(72, top - (len(table) + 2) * 20, "Closing balance 1152.28")
        c.showPage()
    c.save()
    return buf.getvalue()


def scanned_pdf(pages: Sequence[Sequence[str]], *, angle: float = 0.0) -> bytes:
    """Image-only pages (no text layer), each a rendered text image."""
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    for lines in pages:
        image = text_image(lines, angle=angle)
        c.drawImage(ImageReader(image), 0, 0, width=letter[0], height=letter[1])
        c.showPage()
    c.save()
    return buf.getvalue()


def garbage_text_layer_pdf(lines: Sequence[str]) -> bytes:
    """A scan whose invisible text layer is junk (a broken font encoding)."""
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    image = text_image(lines)
    c.drawImage(ImageReader(image), 0, 0, width=letter[0], height=letter[1])
    text = c.beginText(72, 700)
    text.setTextRenderMode(3)  # invisible
    text.setFont("Helvetica", 11)
    for _ in range(10):
        text.textLine("¤¦§¨©«¬®¯°± " * 6)
    c.drawText(text)
    c.showPage()
    c.save()
    return buf.getvalue()


def encrypted_pdf() -> bytes:
    from reportlab.lib.pdfencrypt import StandardEncryption

    buf = io.BytesIO()
    c = canvas.Canvas(
        buf, pagesize=letter, encrypt=StandardEncryption("user-secret", "owner-secret")
    )
    c.drawString(72, 720, "Locked statement")
    c.showPage()
    c.save()
    return buf.getvalue()


def active_content_pdf() -> bytes:
    """A statement carrying JavaScript, a launch action, a URI link and an embedded file."""
    pymupdf: Any = importlib.import_module("pymupdf")  # untyped bindings
    doc = pymupdf.open(stream=statement_pdf(), filetype="pdf")
    page = doc[0]
    page.insert_link(
        {"kind": pymupdf.LINK_LAUNCH, "from": pymupdf.Rect(72, 72, 200, 90), "file": "calc.exe"}
    )
    page.insert_link(
        {
            "kind": pymupdf.LINK_URI,
            "from": pymupdf.Rect(72, 100, 200, 118),
            "uri": "https://tracker.invalid/pixel",
        }
    )
    doc.embfile_add("payload.exe", b"MZ synthetic payload", filename="payload.exe")
    js = doc.get_new_xref()
    doc.update_object(js, "<< /S /JavaScript /JS (app.alert\\('synthetic'\\)) >>")
    doc.xref_set_key(doc.pdf_catalog(), "OpenAction", f"{js} 0 R")
    data: bytes = doc.tobytes()
    doc.close()
    return data


def _png_chunk(kind: bytes, payload: bytes) -> bytes:
    return (
        struct.pack(">I", len(payload))
        + kind
        + payload
        + struct.pack(">I", zlib.crc32(kind + payload) & 0xFFFFFFFF)
    )


def pixel_bomb_png(width: int = 100_000, height: int = 100_000) -> bytes:
    """A tiny PNG whose header claims ``width x height`` pixels (a decompression bomb)."""
    header = struct.pack(">IIBBBBB", width, height, 8, 0, 0, 0, 0)  # 8-bit grayscale
    idat = zlib.compress(b"\x00" * 4096, 9)
    return (
        b"\x89PNG\r\n\x1a\n"
        + _png_chunk(b"IHDR", header)
        + _png_chunk(b"IDAT", idat)
        + _png_chunk(b"IEND", b"")
    )


def receipt_image() -> Image.Image:
    """A narrow, tall thermal-receipt style image."""
    lines = [
        "CORNER MARKET",
        "2026-03-14 12:41",
        "",
        "MILK 2L        3.49",
        "BREAD          2.99",
        "APPLES         4.10",
        "",
        "SUBTOTAL      10.58",
        "TAX            0.85",
        "TOTAL         11.43",
        "CARD **** 1234",
    ]
    return text_image(lines, size=(560, 1500), font_size=34, origin=(30, 60), spacing=70)


def jpeg_with_exif(lines: Sequence[str]) -> bytes:
    """A JPEG scan carrying EXIF data (camera, a GPS-like tag and an orientation)."""
    image = text_image(lines, mode="RGB", size=(1400, 900), origin=(80, 120))
    exif = Image.Exif()
    exif[0x010F] = "SyntheticCam"  # Make
    exif[0x0110] = "Model-0"  # Model
    exif[0x0131] = "perfin-tests"  # Software
    exif[0x0112] = 1  # Orientation: normal
    return image_bytes(image, "JPEG", quality=92, exif=exif.tobytes())


def multipage_tiff(pages: Sequence[Sequence[str]]) -> bytes:
    frames = [text_image(lines, size=(1200, 800), origin=(80, 100)) for lines in pages]
    out = io.BytesIO()
    frames[0].save(out, format="TIFF", save_all=True, append_images=frames[1:], dpi=(300, 300))
    return out.getvalue()


def heic_bytes(lines: Sequence[str]) -> bytes:
    import pillow_heif

    image = text_image(lines, mode="RGB", size=(1200, 800), origin=(80, 100))
    heif = pillow_heif.from_pillow(image)
    out = io.BytesIO()
    heif.save(out, quality=95)
    return out.getvalue()


# -- archives -------------------------------------------------------------------


def zip_bytes(
    members: Sequence[tuple[str, bytes]], *, compression: int = zipfile.ZIP_DEFLATED
) -> bytes:
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w", compression=compression) as archive:
        for name, data in members:
            archive.writestr(name, data)
    return out.getvalue()


def zip_bomb(size: int = 64 * 1024 * 1024) -> bytes:
    """One member of ``size`` zero bytes (compresses about 1000:1)."""
    out = io.BytesIO()
    with (
        zipfile.ZipFile(out, "w", compression=zipfile.ZIP_DEFLATED) as archive,
        archive.open("statement.csv", "w", force_zip64=True) as handle,
    ):
        chunk = b"\x00" * (1024 * 1024)
        for _ in range(size // len(chunk)):
            handle.write(chunk)
    return out.getvalue()


def zip_with_symlink() -> bytes:
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w") as archive:
        info = zipfile.ZipInfo("link-to-secrets")
        info.external_attr = 0o120777 << 16  # symlink
        archive.writestr(info, "/etc/passwd")
        archive.writestr("real.csv", "Date,Amount\n2026-01-01,1.00\n")
    return out.getvalue()


