TRACKING_HTML = """<!DOCTYPE html>
<html><head><title>Your receipt</title>
<style>body { background: url(https://tracker.invalid/bg.png) }</style>
<script>fetch('https://tracker.invalid/beacon')</script>
<link rel="stylesheet" href="https://tracker.invalid/style.css">
</head>
<body>
<p>Thank you for shopping at <b>Corner&nbsp;Market</b>!</p>
<img src="https://tracker.invalid/pixel.gif" width="1" height="1">
<img src="cid:logo@example.invalid" alt="Corner Market logo">
<table><tr><th>Item</th><th>Price</th></tr>
<tr><td>Milk</td><td>3.49</td></tr>
<tr><td>Total</td><td>11.43</td></tr></table>
<p><a href="https://tracker.invalid/click?id=1">View online</a></p>
<iframe src="https://tracker.invalid/frame"></iframe>
<!-- a comment that must vanish -->
</body></html>
"""


def receipt_email(
    *,
    html: str = TRACKING_HTML,
    plain: str | None = None,
    attachments: Sequence[tuple[str, str, bytes]] = (),
    inline_image: bytes | None = None,
    attached_message: bytes | None = None,
) -> bytes:
    """A receipt mail: HTML (and optionally plain) body, a cid image, attachments."""
    msg = EmailMessage(policy=default_policy)
    msg["From"] = "Corner Market <receipts@shop.invalid>"
    msg["To"] = "household+alias-token@perfin.invalid"
    msg["Delivered-To"] = "household+alias-token@perfin.invalid"
    msg["Subject"] = "Your receipt from Corner Market"
    msg["Date"] = "Sat, 14 Mar 2026 12:45:00 +0000"
    msg["Message-ID"] = "<receipt-0001@shop.invalid>"
    msg["Authentication-Results"] = "mx.perfin.invalid; spf=pass; dkim=pass"
    if plain is not None:
        msg.set_content(plain)
        msg.add_alternative(html, subtype="html")
    else:
        msg.set_content(html, subtype="html")
    if inline_image is not None:
        html_part = msg.get_body(preferencelist=("html",))
        assert html_part is not None
        html_part.add_related(
            inline_image, maintype="image", subtype="png", cid="<logo@example.invalid>"
        )
    for name, ctype, data in attachments:
        maintype, subtype = ctype.split("/", 1)
        msg.add_attachment(data, maintype=maintype, subtype=subtype, filename=name)
    if attached_message is not None:
        from email import message_from_bytes

        inner = message_from_bytes(attached_message, policy=default_policy)
        msg.add_attachment(inner)
    return msg.as_bytes()
